<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use Baize\{App,Database,Store,Router,Http,HttpError,Security,Installer,Keyring,Maintenance};
$port=(int)(getenv('BAIZE_TEST_DB_PORT')?:3307);$name='baize_keys_'.bin2hex(random_bytes(4));$admin=new PDO('mysql:host=127.0.0.1;port='.$port,'root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$admin->exec('CREATE DATABASE `'.$name.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_bin');
$dir=sys_get_temp_dir().'/'.$name;mkdir($dir,0700);mkdir($dir.'/keys',0700);mkdir($dir.'/data',0700);$db=new Database(['dsn'=>'mysql:host=127.0.0.1;port='.$port.';dbname='.$name,'user'=>'root','password'=>'']);$config=['public_url'=>'https://analytics.example.test','data_dir'=>$dir.'/data','key_dir'=>$dir.'/keys','master_key'=>random_bytes(32)];$checks=0;$assert=static function(bool $ok,string $why)use(&$checks):void{if(!$ok)throw new RuntimeException($why);$checks++;};$remove=static function(string $path)use(&$remove):void{if(is_dir($path)){foreach(scandir($path) as $f)if($f!=='.'&&$f!=='..')$remove($path.'/'.$f);rmdir($path);}else unlink($path);};
try{
 $app=new App($config,$db);$assert($app->config['master_key']===$config['master_key'],'Fresh pre-migration App can be constructed');$db->migrate();Installer::privateWrite($dir.'/keys/master.v1.key',$config['master_key']);
 $u=['id'=>Store::uuid(),'email'=>'keys@example.test','name'=>'Keys','is_admin'=>true];$app->store->put('users',$u['id'],$u);$token=$app->auth->createSession($u);$headers=['cookie'=>'baize_session='.$token];$router=new Router();Keyring::register($app,$router);Maintenance::register($app,$router);
 $legacy=Security::seal('old-encrypted-credential',$app->config);$result=$router->dispatch(new Http('POST','/api/admin/keys/rotate',[],$headers));$assert($result['version']===2,'First rotation version');$fresh=Security::seal('new-encrypted-credential',$app->config);$assert(json_decode($fresh,true)['v']===2,'New writes use active version');$assert(Security::unseal($legacy,$app->config)==='old-encrypted-credential','Historical version still decrypts');
 $restarted=new App($config,$db);$assert($restarted->config['master_key_version']===2,'Active version persists across process recreation');$assert(Security::unseal($fresh,$restarted->config)==='new-encrypted-credential','Restart decrypts new envelope');
 $result=Keyring::rotate($restarted,$u['id']);$assert($result['version']===3,'Further rotation monotonic');$assert(Security::unseal($legacy,$restarted->config)==='old-encrypted-credential'&&Security::unseal($fresh,$restarted->config)==='new-encrypted-credential','All historical key versions retained');
 foreach([1,2,3] as $v){$s=lstat($dir.'/keys/master.v'.$v.'.key');$assert($s['size']===32&&($s['mode']&0077)===0&&$s['nlink']===1,'Private key material shape');}
 try{$router->dispatch(new Http('POST','/api/admin/keys/rotate',[],['authorization'=>'Bearer denied']));throw new RuntimeException('Bearer could rotate');}catch(HttpError $e){$assert($e->errorCode==='admin_cookie_required','Key rotation browser admin restriction');}
 $status=$router->dispatch(new Http('GET','/api/admin/updates/status',[],$headers));$assert($status['runtime']==='php'&&!$status['configured']&&$status['mechanism']==='manual-package','PHP release status reports actual mechanism');
 try{$router->dispatch(new Http('POST','/api/admin/updates/apply',[],$headers));throw new RuntimeException('PHP ran Node updater');}catch(HttpError $e){$assert($e->errorCode==='PHP_OPERATOR_PACKAGE_UPGRADE','Cross-runtime updater refused explicitly');}
 $encoded=json_encode($db->all('SELECT body FROM documents'));$assert(!str_contains($encoded,bin2hex($app->config['master_key']))&&!str_contains($encoded,'old-encrypted-credential'),'No plaintext keys/credential in database');
 echo json_encode(['suite'=>'keyring','database'=>$db->one('SELECT VERSION() AS v')['v'],'passed'=>$checks])."\n";
}finally{$admin->exec('DROP DATABASE `'.$name.'`');$remove($dir);}
